import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.shared.nokiaunix.generic_if_output import GenericIfOutput

__author__ = "Marcin Usielski"
__copyright__ = "Copyright (C) 2020, Nokia"
__email__ = "marcin.usielski@nokia.com"


class Fpdebug(GenericIfOutput):
    """Fpdebug stats command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Fpgamem command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameters with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Fpdebug, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self._checked_if_ret_required = False
        self._current_stats = None
        self._current_cls = None

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "fpdebug"
        cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Parse command output.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_stats(line=line)
                self._parse_data_line_with_cls(line=line)
                self._parse_data_line(line=line)
                self._parse_cls(line=line)
            except ParsingDone:
                pass
        return super(Fpdebug, self).on_new_line(line, is_full_line)

    # ==== interface stats:
    _re_stats = re.compile(r"=\s+(?P<STATS>\S.*\S)\s+stats")

    def _parse_stats(self, line):
        """
        Parse stats from line of output.

        :param line: Line from connection.
        :return: None
        """
        if self._regex_helper.search_compiled(Fpdebug._re_stats, line):
            self._current_stats = self._regex_helper.group("STATS")
            self.current_ret[self._current_stats] = {}
            self._current_cls = None
            raise ParsingDone()

    # lo-vr0 port:254
    _re_data_line_With_cls = re.compile(r"(?P<CLS>\S+)\s+(?P<KEY>\S+)\s*:\s*(?P<VALUE>\d+)")

    def _parse_data_line_with_cls(self, line):
        if self._regex_helper.search_compiled(Fpdebug._re_data_line_With_cls, line):
            self._current_cls = self._regex_helper.group("CLS")
            key = self._regex_helper.group("KEY")
            value = int(self._regex_helper.group("VALUE"))
            if self._current_stats is not None:
                self.current_ret[self._current_stats][self._current_cls] = {}
                self.current_ret[self._current_stats][self._current_cls][key] = value
            raise ParsingDone()

    # port:254
    _re_data_line = re.compile(r"\s+(?P<KEY>\S+)\s*:\s*(?P<VALUE>\d+)")

    def _parse_data_line(self, line):
        if self._regex_helper.search_compiled(Fpdebug._re_data_line, line):
            key = self._regex_helper.group("KEY")
            value = int(self._regex_helper.group("VALUE"))
            if self._current_stats is not None:
                if self._current_cls is None:
                    self.current_ret[self._current_stats][key] = value
                else:
                    self.current_ret[self._current_stats][self._current_cls][key] = value
            raise ParsingDone()

    # ExceptionByModule:
    _re_cls = re.compile(r"^\s+(?P<CLS>\S+):\s*$")

    def _parse_cls(self, line):
        if self._current_stats and self._regex_helper.search_compiled(Fpdebug._re_cls, line):
            self._current_cls = self._regex_helper.group("CLS")
            self.current_ret[self._current_stats][self._current_cls] = {}


